const raw = $input.first()?.json ?? {};

// אוריגמי עשוי להחזיר את הלידים תחת מפתחות שונים — מנסים כמה אפשרויות
let leads = [];
if (Array.isArray(raw)) leads = raw;
else if (Array.isArray(raw.data)) leads = raw.data;
else if (Array.isArray(raw.leads)) leads = raw.leads;
else if (Array.isArray(raw.results)) leads = raw.results;
else if (Array.isArray(raw.items)) leads = raw.items;
else leads = $input.all().map(i => i.json);

const since = $now.minus({ hours: 24 }).toMillis();

const getDate = (l) => l.createdAt || l.created_at || l.created || l.date || l.insertDate || l.insert_date || l.timestamp || l.dateCreated;
const getPhone = (l) => l.phone || l.phoneNumber || l.phone_number || l.tel || l.mobile || l.cellphone || l.cell || '';
const getName = (l) => l.name || l.fullName || l.full_name || [l.firstName, l.lastName].filter(Boolean).join(' ').trim() || [l.first_name, l.last_name].filter(Boolean).join(' ').trim() || 'ללא שם';
const getSource = (l) => l.source || l.lead_source || l.campaign || l.utm_source || l.utmSource || l.origin || '-';

const filtered = leads.filter((l) => {
  const d = getDate(l);
  if (!d) return true; // אם אין תאריך — לא מסננים החוצה, עדיף לכלול
  const t = new Date(d).getTime();
  return Number.isNaN(t) ? true : t >= since;
});

const today = $now.setZone('Asia/Jerusalem').toFormat('dd/MM/yyyy');

let message;
if (filtered.length === 0) {
  message = `🟢 דוח לידים יומי\n📅 ${today}\n\nאין לידים חדשים מהיממה האחרונה.`;
} else {
  const lines = filtered.map((l, i) => {
    const d = getDate(l);
    let time = '';
    if (d) {
      const dt = new Date(d);
      if (!Number.isNaN(dt.getTime())) {
        time = dt.toLocaleTimeString('he-IL', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Jerusalem' });
      }
    }
    return `${i + 1}. 👤 ${getName(l)}\n   📞 ${getPhone(l)}\n   🎯 מקור: ${getSource(l)}${time ? `\n   🕒 ${time}` : ''}`;
  });
  message = `🟢 לידים חדשים מהיממה האחרונה\n📅 ${today}\nסה\"כ: ${filtered.length} לידים\n\n${lines.join('\n\n')}`;
}

return [{ json: { message, count: filtered.length } }];
